UPDATE t_partner_onboarding_code
SET use_count=use_count+1,
  status=IF(max_uses IS NOT NULL AND use_count>=max_uses,'EXPIRED',status),
  update_time=#{now}
WHERE code_id=#{codeId} AND status='ACTIVE' AND effective_from<=#{now}
  AND (effective_to IS NULL OR effective_to>#{now}) AND (max_uses IS NULL OR use_count<max_uses)
